+#[cfg(test)]
+mod tests {
+    use super::*;
+    use std::cell::{Cell, RefCell};
+
+    #[test]
+    fn callbacks_observe_only_changes_between_stable_values() {
+        let notifications = RefCell::new(Vec::new());
+        let mut reactor = Reactor::new();
+        let input = reactor.create_input(0);
+        let parity = reactor
+            .create_compute(&[CellId::Input(input)], |values| values[0] % 2)
+            .unwrap();
+        let difference = reactor
+            .create_compute(&[CellId::Input(input), CellId::Compute(parity)], |values| {
+                values[0] - values[1]
+            })
+            .unwrap();
+        reactor
+            .add_callback(difference, |value| notifications.borrow_mut().push(value))
+            .unwrap();
+        assert_eq!(reactor.value(CellId::Compute(difference)), Some(0));
+        assert!(notifications.borrow().is_empty());
+
+        assert!(reactor.set_value(input, 1));
+        assert_eq!(reactor.value(CellId::Compute(parity)), Some(1));
+        assert_eq!(reactor.value(CellId::Compute(difference)), Some(0));
+        assert!(notifications.borrow().is_empty());
+
+        assert!(reactor.set_value(input, 2));
+        assert!(reactor.set_value(input, 2));
+        assert_eq!(reactor.value(CellId::Compute(difference)), Some(2));
+        assert_eq!(*notifications.borrow(), [2]);
+    }
+
+    #[test]
+    fn callback_removal_leaves_other_registrations_intact() {
+        let removed_calls = Cell::new(0);
+        let remaining_value = Cell::new(None);
+        let mut reactor = Reactor::new();
+        let input = reactor.create_input(0);
+        let compute = reactor
+            .create_compute(&[CellId::Input(input)], |values| values[0])
+            .unwrap();
+        let other = reactor.create_compute(&[], |_| 0).unwrap();
+        let removed = reactor
+            .add_callback(compute, |_| removed_calls.set(removed_calls.get() + 1))
+            .unwrap();
+        reactor
+            .add_callback(compute, |value| remaining_value.set(Some(value)))
+            .unwrap();
+        assert_eq!(reactor.remove_callback(compute, removed), Ok(()));
+        assert!(reactor.set_value(input, 1));
+        assert_eq!(removed_calls.get(), 0);
+        assert_eq!(remaining_value.get(), Some(1));
+
+        let replacement = reactor.add_callback(compute, |_| {}).unwrap();
+        assert_eq!(
+            reactor.remove_callback(compute, removed),
+            Err(RemoveCallbackError::NonexistentCallback)
+        );
+        assert_eq!(
+            reactor.remove_callback(other, replacement),
+            Err(RemoveCallbackError::NonexistentCallback)
+        );
+    }
+
